 20→/** Map Postmark error codes to user-friendly messages */
 21→function getPostmarkErrorMessage(errorCode: number, message: string, fromEmail: string, toEmail: string): string {
 22→  switch (errorCode) {
 23→    case 412:
 24→      return `Account pending approval — emails can only be sent to @${fromEmail.split("@")[1]} addresses while your Postmark account is being reviewed. You tried sending to ${toEmail}.`;
 25→    case 406:
 26→      return `Inactive recipient — ${toEmail} has been marked as inactive due to previous bounces. Reactivate in Postmark dashboard.`;
 27→    case 300:
 28→      return `Sender signature not found — ${fromEmail} is not verified in Postmark. Add and verify this sender in your Postmark account.`;
 29→    case 400:
 30→      return `Bad request — ${message}`;
 31→    case 401:
 32→      return `Unauthorized — your Postmark API token is invalid or expired. Update it in Email Settings.`;
 33→    case 405:
 34→      return `Not allowed to send — ${message}`;
 35→    case 422:
 36→      return message || "Unprocessable request";
 37→    default:
 38→      return message || `Postmark error (code ${errorCode})`;
 39→  }
 40→}
